109	    pub(crate) fn run(mut self) -> Result<Loaded> {
110	        // First read the source files. This will use the `ModuleLoader`, which
111	        // will check the mtimes and hashes of sources and caches to determine
112	        // which should be loaded.
113	        let mut inputs = self.read_sources_and_caches()?;
114	
115	        // Check for any removed modules, by looking at cache files that don't exist in inputs.
116	        // Delete the cache files for removed modules and mark them as stale
117	        // to trigger refreshing dependent modules.
118	        for module in CacheFiles::modules_with_meta_files(&self.io, &self.artefact_directory) {
119	            if (!inputs.contains_key(&module)) {
120	                tracing::debug!(%module, "module_removed");
121	                CacheFiles::new(&self.artefact_directory, &module).delete(&self.io)?;
122	                self.stale_modules.add(module);
123	            }
124	        }
125	
126	        // Determine order in which modules are to be processed
127	        let mut dep_location_map = HashMap::new();
128	        let deps = inputs
129	            .values()
130	            .map(|m| {
131	                let name = m.name().clone();
132	                let _ = dep_location_map.insert(name.clone(), m);
133	                (name, m.dependencies())
134	            })
135	            // Making sure that the module order is deterministic, to prevent different
136	            // compilations of the same project compiling in different orders. This could impact
137	            // any bugged outcomes, though not any where the compiler is working correctly, so it's
138	            // mostly to aid debugging.
139	            .sorted_by(|(a, _), (b, _)| a.cmp(b))
140	            .collect();
141	        let sequence = dep_tree::toposort_deps(deps)
142	            .map_err(|e| self.convert_deps_tree_error(e, dep_location_map))?;
143	
144	        // Now that we have loaded sources and caches we check to see if any of
145	        // the caches need to be invalidated because their dependencies have
146	        // changed.
147	        let mut loaded = Loaded::default();
148	        for name in sequence {
149	            let input = inputs
150	                .remove(&name)
151	                .expect("Getting parsed module for name");
152	
153	            match input {
154	                // A new uncached module is to be compiled
155	                Input::New(module) => {
156	                    tracing::debug!(module = %module.name, "new_module_to_be_compiled");
157	                    self.stale_modules.add(module.name.clone());
158	                    loaded.to_compile.push(module);
159	                }
160	
161	                // A cached module with dependencies that are stale must be
162	                // recompiled as the changes in the dependencies may have affect
163	                // the output, making the cache invalid.
164	                Input::Cached(info) if self.stale_modules.includes_any(&info.dependencies) => {
165	                    tracing::debug!(module = %info.name, "stale_module_to_be_compiled");
166	                    self.stale_modules.add(info.name.clone());
167	                    let module = self.load_stale_module(info)?;
168	                    loaded.to_compile.push(module);
169	                }
170	
171	                // A cached module with no stale dependencies can be used as-is
172	                // and does not need to be recompiled.
173	                Input::Cached(info) => {
174	                    tracing::debug!(module = %info.name, "module_to_load_from_cache");
175	                    let module = self.load_cached_module(info)?;
176	                    loaded.cached.push(module);
177	                }
178	            }
179	        }
180	
181	        Ok(loaded)
182	    }

